#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_URL_LENGTH 256

char* get_url_to_visit(const char* domain, const char* subdomain_prefix) {
    char url[MAX_URL_LENGTH];
    char* result = (char*)malloc(MAX_URL_LENGTH * sizeof(char));

    if (!result) {
        return NULL;
    }

    // Check if subdomain is valid and not empty
    if (subdomain_prefix && strlen(subdomain_prefix) > 0) {
        // Ensure the combined length does not exceed MAX_URL_LENGTH
        if (strlen(subdomain_prefix) + strlen(domain) + 6 < MAX_URL_LENGTH) {
            snprintf(url, MAX_URL_LENGTH, "https://%s.%s", subdomain_prefix, domain);
        } else {
            free(result);
            return NULL;
        }
    } else {
        // Default to the domain itself
        if (strlen(domain) + 7 < MAX_URL_LENGTH) {
            snprintf(url, MAX_URL_LENGTH, "https://%s", domain);
        } else {
            free(result);
            return NULL;
        }
    }

    strcpy(result, url);
    return result;
}
